//@version=5
indicator("LBMA 黄金定盘时间", overlay=true)

// ==================== 用户自定义时间设置 ====================
// 夏令时时间设置（北京时间）
summer_time1_hour = https://t.co/ymJTKCbK1L(17, "夏令时 - 第一条线 小时", minval=0, maxval=23, group="夏令时设置")
summer_time1_min = https://t.co/ymJTKCbK1L(30, "夏令时 - 第一条线 分钟", minval=0, maxval=59, group="夏令时设置")
summer_time2_hour = https://t.co/ymJTKCbK1L(22, "夏令时 - 第二条线 小时", minval=0, maxval=23, group="夏令时设置")
summer_time2_min = https://t.co/ymJTKCbK1L(0, "夏令时 - 第二条线 分钟", minval=0, maxval=59, group="夏令时设置")

// 冬令时时间设置（北京时间）
winter_time1_hour = https://t.co/ymJTKCbK1L(18, "冬令时 - 第一条线 小时", minval=0, maxval=23, group="冬令时设置")
winter_time1_min = https://t.co/ymJTKCbK1L(30, "冬令时 - 第一条线 分钟", minval=0, maxval=59, group="冬令时设置")
winter_time2_hour = https://t.co/ymJTKCbK1L(23, "冬令时 - 第二条线 小时", minval=0, maxval=23, group="冬令时设置")
winter_time2_min = https://t.co/ymJTKCbK1L(0, "冬令时 - 第二条线 分钟", minval=0, maxval=59, group="冬令时设置")

// 线条样式设置
line1_color = input.color(https://t.co/Ltg0hywbfc(https://t.co/wwKN6G8WQi, 0), "第一条线颜色", group="样式设置")
line2_color = input.color(https://t.co/Ltg0hywbfc(https://t.co/OoWW6l3jRA, 0), "第二条线颜色", group="样式设置")
line_width = https://t.co/ymJTKCbK1L(1, "线条宽度", minval=1, maxval=4, group="样式设置")
line_style_input = input.string("虚线", "线条样式", options=["实线", "虚线", "点线"], group="样式设置")

// 转换线条样式
line_style = line_style_input == "实线" ? https://t.co/BSny5nuXgY_solid : line_style_input == "虚线" ? https://t.co/BSny5nuXgY_dashed : https://t.co/BSny5nuXgY_dotted

// ==================== 夏令时判断函数 ====================
// 美国夏令时规则：3月第二个周日 02:00 开始，11月第一个周日 02:00 结束
// 返回true表示当前是夏令时

isDST(int y, int m, int d) =>
// 1月和2月一定是冬令时
if m < 3
false
// 12月一定是冬令时
else if m > 11
false
// 4-10月一定是夏令时
else if m > 3 and m < 11
true
// 3月：需要判断是否过了第二个周日
else if m == 3
// 计算3月1日是星期几 (0=周日, 1=周一, ..., 6=周六)
// 使用蔡勒公式的简化版本
int yy = y
int mm = m
if mm < 3
mm := mm + 12
yy := yy - 1
int q = 1 // 3月1日
int k = yy % 100
int j = yy / 100
int h = (q + (13 * (mm + 1)) / 5 + k + k / 4 + j / 4 - 2 * j) % 7
int dow_mar1 = (h + 6) % 7 // 转换为 0=周日
// 第二个周日的日期
int second_sunday = dow_mar1 == 0 ? 8 : (7 - dow_mar1) + 8
d >= second_sunday
// 11月：需要判断是否还没到第一个周日
else // m == 11
// 计算11月1日是星期几
int yy = y
int mm = m
int q = 1 // 11月1日
int k = yy % 100
int j = yy / 100
int h = (q + (13 * (mm + 1)) / 5 + k + k / 4 + j / 4 - 2 * j) % 7
int dow_nov1 = (h + 6) % 7 // 转换为 0=周日
// 第一个周日的日期
int first_sunday = dow_nov1 == 0 ? 1 : (7 - dow_nov1) + 1
d < first_sunday
// ==================== 获取当前时间信息（北京时间 UTC+8） ====================
current_hour = hour(time, "UTC+8")
current_min = minute(time, "UTC+8")
current_year = year(time, "UTC+8")

current_month = month(time, "UTC+8")
current_day = dayofmonth(time, "UTC+8")
// 判断当前是否为夏令时
is_dst = isDST(current_year, current_month, current_day)
// 根据夏令时/冬令时选择对应的时间
time1_hour = is_dst ? summer_time1_hour : winter_time1_hour

time1_min = is_dst ? summer_time1_min : winter_time1_min
time2_hour = is_dst ? summer_time2_hour : winter_time2_hour

time2_min = is_dst ? summer_time2_min : winter_time2_min
// ==================== 判断是否需要画线 ====================
// 检查当前K线是否是指定时间的第一根K线
is_time1 = current_hour == time1_hour and current_min == time1_min
is_time2 = current_hour == time2_hour and current_min == time2_min

// 避免在同一时间点重复画线
is_new_time1 = is_time1 and not is_time1[1]
is_new_time2 = is_time2 and not is_time2[1]
// ==================== 画竖线 ====================

if is_new_time1
https://t.co/0CTliwUdIe(bar_index, low, bar_index, high, extend=extend.both, color=line1_color, width=line_width, style=line_style)
if is_new_time2

https://t.co/0CTliwUdIe(bar_index, low, bar_index, high, extend=extend.both, color=line2_color, width=line_width, style=line_style)
// ==================== 显示当前状态标签 ====================
show_label = input.bool(true, "显示状态标签", group="样式设置")

if barstate.islast and show_label
label_text = is_dst ? "☀️ 夏令时\n" + str.tostring(time1_hour) + ":" + str.tostring(time1_min, "00") + " / " + str.tostring(time2_hour) + ":" + str.tostring(time2_min, "00") : "❄️ 冬令时\n" + str.tostring(time1_hour) + ":" + str.tostring(time1_min, "00") + " / " + str.tostring(time2_hour) + ":" + str.tostring(time2_min, "00")

var label status_label = na
if not na(status_label)

label.delete(status_label)
status_label := https://t.co/CWMQVGCePM(bar_index + 5, high, label_text, style=https://t.co/49nIN3ebKi_label_left, color=is_dst ? https://t.co/Ltg0hywbfc(https://t.co/wwKN6G8WQi, 80) : https://t.co/Ltg0hywbfc(https://t.co/OoWW6l3jRA, 80), textcolor=is_dst ? https://t.co/wwKN6G8WQi : https://t.co/OoWW6l3jRA, size=size.normal)
// ==================== 背景色提示（可选） ====================
show_bg = input.bool(false, "显示时段背景色", group="样式设置")
bgcolor(show_bg and is_time1 ? https://t.co/Ltg0hywbfc(line1_color, 90) : na)
bgcolor(show_bg and is_time2 ? https://t.co/Ltg0hywbfc(line2_color, 90) : na)

